  for(const[k,kw]of UX_PAGE_RULES){const s=kw.reduce((n,w)=>n+(a.includes(w)?1:0),0);if(s>best){best=s;type=k}}
  if(!best&&a.replace(/\s+/g,'').length<40)type='shop_photo';
